mesSim(document.getElementById("sim-l64"),Object.assign({id:"l64"},{kind:"term",title:"Chạy collector lâu dài và giám sát",sub:"Lệnh schtasks tạo tác vụ Task Scheduler (WINDOWS_QA_PENDING). psql truy vấn bảng nhịp tim của collector.",cwd:"C:\\amts\\mini-mes",vars:{task:false,run:false,restart:false,killedAt:null,t:0},
 hints:["schtasks /Create /TN MES-Collector /TR \"C:\\amts\\mini-mes\\run_collector.cmd\" /SC ONSTART /RU SYSTEM","schtasks /Run /TN MES-Collector","Get-Process python","Stop-Process -Name python","psql -U mes_app -d mes_dev -c \"SELECT collector_id, now() - last_seen AS im_lang FROM mes.collector_heartbeat\""],
 cmds:[{re:/^schtasks \/Create \/TN MES-Collector .*\/SC ONSTART.*$/i,out:"SUCCESS: The scheduled task \"MES-Collector\" has successfully been created.\n(Nhớ bật “If the task fails, restart every 1 minute” trong thẻ Settings.)",fx:(m,S)=>{S.task=true}},
  {re:/^schtasks \/Run \/TN MES-Collector$/i,out:(m,S)=>S.task?"SUCCESS: Attempted to run the scheduled task \"MES-Collector\".":{err:"ERROR: The system cannot find the file specified."},fx:(m,S)=>{if(S.task){S.run=true;S.killedAt=null}}},
  {re:/^Get-Process python$/i,out:(m,S)=>S.run?"Handles  NPM(K)  PM(K)  WS(K)  Id ProcessName\n    210      18  32156  41220 4812 python":{err:"Get-Process : Cannot find a process with the name \"python\"."}},
  {re:/^Stop-Process -Name python$/i,out:"",fx:(m,S)=>{if(S.run){S.run=false;S.killedAt=Date.now()}}},
  {re:/^psql .*collector_heartbeat.*$/i,out:(m,S)=>" collector_id | im_lang\n--------------+----------\n L1           | "+(S.run?"00:00:04":S.killedAt?"00:01:12   ← quá 60 s: bảng giám sát đỏ":"(chưa có)")+"\n(1 row)"}],
 tasks:[{t:"Tạo tác vụ MES-Collector chạy khi khởi động, rồi chạy nó và kiểm tra tiến trình.",check:(s,c)=>s.S.task&&s.S.run&&s.ran(/^Get-Process python$/i)},
  {t:"Xem nhịp tim của collector trong CSDL.",check:(s,c)=>c.has("cmd",e=>/collector_heartbeat/.test(e.line)&&/00:00:04/.test(e.out))},
  {t:"Giết tiến trình collector rồi xem lại nhịp tim.",ok:"last_seen cũ hơn 60 s: giám sát báo collector chết. Máy vẫn chạy, chỉ MES mù: nhịp tim D106 cho biết PLC sống, nhịp tim collector cho biết collector sống.",check:(s,c)=>c.has("cmd",e=>/collector_heartbeat/.test(e.line)&&/quá 60 s/.test(e.out))}]}));

